function dHead(d,to){const c=d.client||{};return[(c.nom||'[Nom prénom]'),(c.adresse||'[Adresse]'),((c.cp||'[CP]')+' '+(c.ville||'[Ville]')),'Tél : '+(c.tel||'[Tél]')+' — '+(c.email||'[Email]'),'',(to||d.vendeur.nom||'[Destinataire]'),(d.vendeur.adresse||'[Adresse]'),'','Lettre recommandée avec accusé de réception','Objet : '+d.titre,'Réf : '+d.ref,(c.ville||'[Ville]')+', le '+new Date().toLocaleDateString('fr-FR'),'','Madame, Monsieur,'].join('\n')}
function dFacts(d){const v=d.veh||{};const l=['Acquéreur du véhicule '+[v.marque,v.modele,v.motor,v.annee].filter(Boolean).join(' ')+(v.vin?' (VIN '+v.vin+')':'')+', acheté le '+(v.achat||'[date]')+' au prix de '+(v.prix||'[montant]')+' €.'];if(d.faits)l.push('Faits : '+d.faits);if(d.etude&&d.etude.top&&d.etude.top.length)l.push('Constatations : '+d.etude.top.map(k=>k.t+' ('+k.dtc.join(', ')+')').join(' ; ')+'.');return l.join('\n')}
function dFoot(d){return['','Mise en demeure d\'y faire droit sous QUINZE (15) JOURS. À défaut, saisine de la juridiction compétente et dommages-intérêts (1231-6 C. civ.).','','Veuillez agréer, Madame, Monsieur, mes salutations distinguées.','',(d.client.nom||'[Signature]'),'','Pièces : facture, constatations, devis, photographies.'].join('\n')}
const TEMPLATES={
med:{n:'Mise en demeure LRAR',fn:d=>{const b=d.cat==='conformite'?'L217-3 et s. C. conso.':d.cat==='dol'?'1137 C. civ. (dol)':d.cat==='reparateur'?'1231-1 C. civ. (obligation de résultat)':'1641 et s. C. civ. (vices cachés)';return dHead(d)+'\n\n'+dFacts(d)+'\n\nDésordres cachés et antérieurs rendant le véhicule impropre à l\'usage. En application de '+b+', je demande :\n— à titre principal, résolution et restitution du prix ;\n— subsidiaire, réduction du prix.\n'+dFoot(d)}},
medconfo:{n:'Mise en conformité LRAR',fn:d=>dHead(d)+'\n\n'+dFacts(d)+'\n\nDéfaut de conformité (L217-3 et s.), présumé à la délivrance (L217-7). Je demande la MISE EN CONFORMITÉ par réparation/remplacement, sans frais, sous TRENTE (30) JOURS (L217-10). À défaut, réduction ou résolution.\n'+dFoot(d)},
expertise:{n:'Convocation expertise contradictoire',fn:d=>dHead(d)+'\n\n'+dFacts(d)+'\n\nJe vous convoque à une expertise amiable contradictoire le [DATE] à [HEURE], à [LIEU], en présence de [expert]. À défaut de votre présence, l\'expertise sera réputée contradictoire.\n\nMes salutations distinguées.\n\n'+(d.client.nom||'[Signature]')},
mediation:{n:'Saisine médiateur conso',fn:d=>'SAISINE MÉDIATEUR DE LA CONSOMMATION\n\nRéf : '+d.ref+'\n'+(d.client.nom||'[Nom]')+' — '+(d.client.email||'[Email]')+'\nContre : '+(d.vendeur.nom||'[Vendeur pro]')+'\n\n'+dFacts(d)+'\n\nRéclamation le [date], LRAR le [date], sans solution. Demande : '+(d.cat==='conformite'?'mise en conformité/remboursement.':'résolution/réduction.')+'\nPièces : facture, LRAR+AR, constatations, devis, photos.'},
dgccrf:{n:'Signalement sécurité',fn:d=>'SIGNALEMENT DÉFAUT DE SÉCURITÉ\n\nVéhicule : '+[d.veh.marque,d.veh.modele,d.veh.motor,d.veh.annee].filter(Boolean).join(' ')+' — VIN '+(d.veh.vin||'[VIN]')+'\n\n'+dFacts(d)+'\n\nRisque : '+(d.etude&&d.etude.fires&&d.etude.fires.length?d.etude.fires.map(f=>f.ch).join(' ; '):'incendie/défaut sécurité')+'.\nFondement : L421-3 C. conso. → signal.conso.gouv.fr / DGCCRF.'},
assurance:{n:'Déclaration sinistre incendie',fn:d=>'DÉCLARATION SINISTRE INCENDIE\n\nAssuré : '+(d.client.nom||'[Nom]')+' — Contrat n° [numéro]\nVéhicule : '+[d.veh.marque,d.veh.modele,d.veh.annee].filter(Boolean).join(' ')+' — VIN '+(d.veh.vin||'[VIN]')+'\nDate/lieu : [date] à [lieu]\nCirconstances : '+(d.faits||'[déroulement]')+'\n\n'+(d.etude&&d.etude.fires&&d.etude.fires.length?'Origine pressentie : '+d.etude.fires.map(f=>f.t+' — '+f.ch).join(' ; '):'Origine à déterminer.')+'\n\nDéclaration sous 5 jours ouvrés, demande d\'expertise. Pièces conservées.\n\n'+(d.client.ville||'[ville]')+', le '+new Date().toLocaleDateString('fr-FR')+'\n'+(d.client.nom||'[Signature]')},
assignation:{n:'Projet d\'assignation (avocat)',fn:d=>'PROJET D\'ASSIGNATION — TRIBUNAL JUDICIAIRE\n⚠️ Trame — à valider par avocat/commissaire de justice.\n\nDEMANDEUR : '+(d.client.nom||'[Nom]')+', '+(d.client.adresse||'[adresse]')+'\nDÉFENDEUR : '+(d.vendeur.nom||'[Vendeur]')+', '+(d.vendeur.adresse||'[adresse]')+'\n\nFAITS :\n'+dFacts(d)+'\nLRAR du [date] infructueuse. Tentative amiable : [date].\n\nDISCUSSION : '+(PROCEDURES[d.cat]?PROCEDURES[d.cat].law.map(id=>{const x=LEGAL.find(y=>y.id===id);return x?x.ref+' — '+x.t:''}).join(' ; '):'')+'\n\nPAR CES MOTIFS : résolution + restitution '+(d.veh.prix||'[montant]')+' € ; DI [montant] € ; exécution provisoire ; dépens (700 CPC).\nPIÈCES : facture, LRAR+AR, expertise, devis, photos, DTC.'}};
