const JR_DEFENSE_COMMON=['Charge de la preuve sur le demandeur (art. 1353 C. civ.)','Prescription / forclusion (2224, 1648, 2232 C. civ.)','Absence de lien de causalité démontré','Force majeure / cause étrangère (1218, 1231-1 C. civ.)','Faute de la victime / partage de responsabilité','Contestation du chiffrage (absence de justificatifs, exagération)'];
function JRDOC_head(d){const c=d.client||{};return[(c.nom||'[Nom prénom]'),(c.adresse||'[Adresse]'),((c.cp||'[CP]')+' '+(c.ville||'[Ville]')),'Tél : '+(c.tel||'[Tél]')+' — '+(c.email||'[Email]'),'',(d.dest||'[Destinataire]'),'','Lettre recommandée avec accusé de réception',(c.ville||'[Ville]')+', le '+new Date().toLocaleDateString('fr-FR'),'','Madame, Monsieur,'].join('\n')}
function JRDOC_foot(d){return['','Mise en demeure d\'y faire droit sous QUINZE (15) JOURS. À défaut, saisine de la juridiction compétente et dommages-intérêts (1231-6 C. civ.).','','Veuillez agréer, Madame, Monsieur, mes salutations distinguées.','',(d.client.nom||'[Signature]')].join('\n')}
const JR_DOCS={
lrar:{n:'Mise en demeure LRAR',fn:(d,r)=>JRDOC_head(d)+'\n\nSituation : '+d.desc+'\n\nResponsabilité : '+(r.parties[0]?r.parties[0][0]+' — '+r.parties[0][1]:'')+'.\nFondements : '+r.texts.map(id=>{const t=JR_TEXTS.find(x=>x.id===id)||LEGAL.find(x=>x.id===id);return t?t.ref:''}).filter(Boolean).join(' ; ')+'.\n\nJe vous demande de [cesser le trouble / exécuter / rembourser / indemniser].\n'+JRDOC_foot(d)},
retract:{n:'Rétractation / annulation (14/30 j)',fn:(d,r)=>JRDOC_head(d)+'\n\nCommande/contrat du [date] — réf [numéro].\n'+d.desc+'\n\nEn application de L221-18 (rétractation 14 j) / L216-1 (livraison 30 j), je me rétracte / j\'annule et demande le remboursement intégral sous 14 jours.\n'+JRDOC_foot(d)},
sinistre:{n:'Déclaration de sinistre',fn:(d,r)=>'DÉCLARATION DE SINISTRE\n\nAssuré : '+(d.client.nom||'[Nom]')+' — Contrat n° [numéro]\nDate/lieu : '+(d.dateLieu||'[date/lieu]')+'\n\n'+d.desc+'\n\nDéclaration dans le délai de 5 jours ouvrés (L113-2 C. assur.), demande d\'expertise et de provision (Badinter / L211-9).\nPièces : constat, photos, certificat médical, rapport.\n\n'+new Date().toLocaleDateString('fr-FR')+' — '+(d.client.nom||'[Signature]')},
mediation:{n:'Saisine médiateur / conciliateur',fn:(d,r)=>'SAISINE MÉDIATEUR / CONCILIATEUR\n\nRéf : '+d.ref+'\nDemandeur : '+(d.client.nom||'[Nom]')+' — '+(d.client.email||'[Email]')+'\nContre : '+(d.dest||'[Partie adverse]')+'\n\n'+d.desc+'\n\nRéclamation LRAR du [date] sans solution. Demande : [préciser].\nFondements : '+r.texts.map(id=>{const t=JR_TEXTS.find(x=>x.id===id)||LEGAL.find(x=>x.id===id);return t?t.ref:''}).filter(Boolean).join(' ; ')+'.\nPièces jointes.'},
expertise:{n:'Demande / convocation d\'expertise',fn:(d,r)=>JRDOC_head(d)+'\n\n'+d.desc+'\n\nJe sollicite une expertise amiable contradictoire le [DATE] à [LIEU], en présence de [expert], pour établir causes et préjudices. À défaut de votre présence, l\'expertise sera réputée contradictoire.\n\nMes salutations distinguées.\n\n'+(d.client.nom||'[Signature]')},
plainte:{n:'Dépôt de plainte / signalement',fn:(d,r)=>'PLAINTE / SIGNALEMENT\n\nPlaignant : '+(d.client.nom||'[Nom]')+'\n\n'+d.desc+'\n\nQualification : '+r.texts.map(id=>{const t=JR_TEXTS.find(x=>x.id===id)||LEGAL.find(x=>x.id===id);return t?t.t:''}).filter(Boolean).join(' ; ')+'.\n\nJe dépose plainte entre les mains de [procureur / commissariat / CNIL / DGCCRF].\nPièces : [liste].\n\n'+new Date().toLocaleDateString('fr-FR')+' — '+(d.client.nom||'[Signature]')},
prud:{n:'Saisine prud\'hommes (trame)',fn:(d,r)=>'REQUÊTE — CONSEIL DE PRUD\'HOMMES\n⚠️ Trame — à valider (avocat / défenseur syndical).\n\nDemandeur : '+(d.client.nom||'[Nom]')+' — Défendeur : '+(d.dest||'[Employeur]')+'\n\n'+d.desc+'\n\nFondements : '+r.texts.map(id=>{const t=JR_TEXTS.find(x=>x.id===id)||LEGAL.find(x=>x.id===id);return t?t.ref:''}).filter(Boolean).join(' ; ')+'.\n\nDemandes : rappel de salaire / indemnités (L1235-3) / DI / nullité.\nPièces : contrat, bulletins, lettre, échanges, attestations.'},
rgpd:{n:'Demande d\'effacement RGPD',fn:(d,r)=>JRDOC_head(d)+'\n\nEn application du RGPD (art. 17 — effacement) et de la loi Informatique et Libertés, je demande la suppression des données me concernant [préciser], confirmée sous un mois.\n\nÀ défaut, je saisirai la CNIL.\n'+JRDOC_foot(d)},
dgccrf:{n:'Signalement DGCCRF / RappelConso',fn:(d,r)=>'SIGNALEMENT — PRATIQUE / SÉCURITÉ\n\n'+d.desc+'\n\nFondements : '+r.texts.map(id=>{const t=JR_TEXTS.find(x=>x.id===id)||LEGAL.find(x=>x.id===id);return t?t.ref:''}).filter(Boolean).join(' ; ')+'.\n→ signal.conso.gouv.fr / DGCCRF.'},
assignation:{n:'Projet d\'assignation (avocat)',fn:(d,r)=>'PROJET D\'ASSIGNATION\n⚠️ Trame — avocat / commissaire de justice.\n\nDemandeur : '+(d.client.nom||'[Nom]')+' — Défendeur : '+(d.dest||'[Partie adverse]')+'\n\nFAITS : '+d.desc+'\nLRAR du [date] infructueuse. Tentative amiable : [date].\n\nDISCUSSION : '+r.texts.map(id=>{const t=JR_TEXTS.find(x=>x.id===id)||LEGAL.find(x=>x.id===id);return t?t.ref+' — '+t.t:''}).filter(Boolean).join(' ; ')+'.\n\nPAR CES MOTIFS : juger la responsabilité établie ; condamner à [montant] € ; exécution provisoire ; dépens (700 CPC).\nPièces : [bordereau].'},
reponse:{n:'Réponse en défense (défenseur)',fn:(d,r)=>JRDOC_head(d)+'\n\nVous me réclamez [préciser] au titre de : '+d.desc+'\n\nJe conteste cette réclamation pour les motifs suivants :\n'+(r.defense||JR_DEFENSE_COMMON).map((x,i)=>(i+1)+'. '+x).join('\n')+'\n\nEn application de l\'article 1353 C. civ., il vous appartient de rapporter la preuve de votre demande. Je vous invite à produire tout justificatif, à défaut de quoi je m\'opposerai à toute action.\n\nSous toutes réserves.\n\n'+(d.client.nom||'[Signature]')}};
